}

fn square(n: i32) ___ i32 {
    n * n
}

fn sign(n: i32) -> i32 {
    if n < 0 {
        return -1;
    }
    1
}

fn main() {
    println!("{} {}", sign(-5), sign(5));
}

fn step(n: i32) -> i32 {
    let m = n + 1;
    m * 2
}

fn main() {
    let a = step(1);
    let b = step(a);
    println!("{a} {b}");
}
